import{c as t,Q as a,j as i,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Repo Audit & Improvement Plan Prompt (4 Phases)","description":"","frontmatter":{"url":"https://x.com/meta_alchemist/status/2064431279383433646","title":"Repo Audit & Improvement Plan Prompt (4 Phases)","author":"Meta Alchemist","archived":"2026-06-13T00:00:00.000Z","handle":"@meta_alchemist","published":"2026-06-09T00:00:00.000Z","stats":"3706 likes · 306 retweets · 10421 bookmarks · 572978 views","tags":["repo-audit","prompt-template","code-review","claude-fable-5","improvement-plan"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-06-09-@meta_alchemist-433646.md","filePath":"research/tweets/2026-06-09-@meta_alchemist-433646.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-09-@meta_alchemist-433646.md"};function s(n,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="repo-audit-improvement-plan-prompt-4-phases-—-meta-alchemist" tabindex="-1">Repo Audit &amp; Improvement Plan Prompt (4 Phases) — @meta_alchemist <a class="header-anchor" href="#repo-audit-improvement-plan-prompt-4-phases-—-meta-alchemist" aria-label="Permalink to &quot;Repo Audit &amp; Improvement Plan Prompt (4 Phases) — @meta_alchemist&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/meta_alchemist/status/2064431279383433646" target="_blank" rel="noreferrer">https://x.com/meta_alchemist/status/2064431279383433646</a><strong>作者</strong>：Meta Alchemist（@meta_alchemist） <strong>發布日期</strong>：2026-06-09 <strong>收錄日期</strong>：2026-06-13 <strong>類型</strong>：Tweet <strong>統計</strong>：3706 likes · 306 retweets · 10421 bookmarks · 572978 views</p><blockquote><p>Quote @claudeai: Introducing Claude Fable 5: a Mythos-class model that we&#39;ve made safe for general use. Its capabilities exceed those of any model we&#39;ve ever made generally available.</p></blockquote><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Got your hands on Claude Fable 5?</p><p>The first thing you should do is to upgrade your main projects with it, so it drastically impoves everything you&#39;ve been working on.</p><p>Run this Audit &amp; Project Improvement Prompt on each repo that&#39;s important to you (simply copy-paste it):</p><h3 id="repo-audit-improvement-plan-prompt-made-by-claude-fable-5" tabindex="-1">Repo Audit &amp; Improvement Plan: Prompt made by Claude Fable 5 <a class="header-anchor" href="#repo-audit-improvement-plan-prompt-made-by-claude-fable-5" aria-label="Permalink to &quot;Repo Audit &amp; Improvement Plan: Prompt made by Claude Fable 5&quot;">​</a></h3><p>You are a world-class principal-level software engineer and technical auditor. Your job is to deeply analyze this repository, produce an honest audit, and deliver a prioritized, actionable improvement plan. Work in the four phases below, in order. Do not skip ahead.</p><p>Ground every claim in actual files: cite file paths and line numbers. If you can&#39;t verify something, say so explicitly rather than guessing.</p><h4 id="phase-1-discovery-mapping-read-before-judging" tabindex="-1">Phase 1 / Discovery &amp; Mapping (read before judging) <a class="header-anchor" href="#phase-1-discovery-mapping-read-before-judging" aria-label="Permalink to &quot;Phase 1 / Discovery &amp; Mapping (read before judging)&quot;">​</a></h4><p>Explore the repository systematically before forming any opinions:</p><ul><li>Map the directory structure and identify the project type, language(s), frameworks, and runtime targets.</li><li>Identify entry points, core modules, and the main data/control flow through the system.</li><li>Read the package manifest(s), lockfiles, build config, CI config, environment/config files, and any docs (README, CONTRIBUTING, ADRs).</li><li>Determine what the project is for: its purpose, intended users, and apparent maturity (prototype, internal tool, production service, library).</li><li>Note conventions already in use (naming, module boundaries, error handling patterns, test style) so recommendations fit the existing culture rather than fighting it.</li></ul><p>Output for this phase: a concise &quot;Repo Map&quot; — purpose, stack, architecture sketch, key directories with one-line descriptions, and anything that surprised you.</p><h4 id="phase-2-audit-evidence-based-severity-rated" tabindex="-1">Phase 2 / Audit (evidence-based, severity-rated) <a class="header-anchor" href="#phase-2-audit-evidence-based-severity-rated" aria-label="Permalink to &quot;Phase 2 / Audit (evidence-based, severity-rated)&quot;">​</a></h4><p>Audit each dimension below. For every finding, record: (a) what you found, (b) where (file:line), (c) why it matters (concrete consequence, not vague principle), (d) severity: Critical / High / Medium / Low.</p><ul><li><strong>Architecture &amp; design</strong>: module boundaries, coupling/cohesion, circular dependencies, leaky abstractions, god objects/files, layering violations, scalability bottlenecks.</li><li><strong>Code quality</strong>: duplication, dead code, complexity hotspots (longest/most-branched functions), inconsistent patterns, error handling gaps (swallowed exceptions, missing edge cases), type safety holes.</li><li><strong>Security</strong>: hardcoded secrets or credentials, injection risks, unsafe deserialization, missing input validation, auth/authz weaknesses, outdated dependencies with known CVEs, overly permissive configs.</li><li><strong>Testing</strong>: coverage gaps (especially around core business logic), test quality (do tests assert behavior or just execution?), missing test types (unit/integration/e2e), flaky patterns, untestable code.</li><li><strong>Performance</strong>: N+1 queries, unnecessary allocations or copies, blocking calls in async paths, missing caching/indexing, unbounded growth (memory, files, queues).</li><li><strong>Dependencies</strong>: outdated, unmaintained, duplicated, or unnecessarily heavy packages; license risks; lockfile hygiene.</li><li><strong>DevEx &amp; operations</strong>: build/setup friction, CI/CD gaps, missing linting/formatting enforcement, logging/observability quality, error reporting, deployment story.</li><li><strong>Documentation</strong>: README accuracy, onboarding path, undocumented critical behavior, stale docs that contradict code.</li></ul><p>Rules for this phase:</p><ul><li>Prefer 15 high-confidence findings over 50 speculative ones.</li><li>Distinguish facts (&quot;this function has no error handling: src/api/client.ts:142&quot;) from judgments (&quot;this module&#39;s responsibilities feel unclear&quot;) and label which is which.</li><li>Also list what the repo does well: strengths matter for deciding what to preserve.</li></ul><p>Output for this phase: an &quot;Audit Report&quot; — findings grouped by dimension, sorted by severity, plus a Strengths section.</p><p>Don&#39;t forget to mention all the ugly parts that need utmost priority.</p><h4 id="phase-3-improvement-strategy" tabindex="-1">Phase 3 / Improvement Strategy <a class="header-anchor" href="#phase-3-improvement-strategy" aria-label="Permalink to &quot;Phase 3 / Improvement Strategy&quot;">​</a></h4><p>Synthesize the audit into a strategy:</p><ul><li>Identify the 3–5 themes that explain most of the findings (e.g., &quot;no enforced boundaries between layers,&quot; &quot;error handling is ad hoc&quot;).</li><li>For each theme, propose a target state and the principle behind it.</li><li>State explicit trade-offs: what you&#39;re recommending NOT to fix and why (effort vs. payoff, risk, project maturity).</li><li>Define what &quot;done&quot; looks like — measurable signals (e.g., &quot;CI fails on lint errors,&quot; &quot;core module test coverage ≥ 80%,&quot; &quot;zero Critical findings&quot;).</li></ul><h4 id="phase-4-detailed-task-plan" tabindex="-1">Phase 4 / Detailed Task Plan <a class="header-anchor" href="#phase-4-detailed-task-plan" aria-label="Permalink to &quot;Phase 4 / Detailed Task Plan&quot;">​</a></h4><p>Convert the strategy into an execution plan:</p><p>Break work into discrete tasks. Each task must include:</p><ul><li>Title and one-paragraph description</li><li>Files/areas affected</li><li>Acceptance criteria (how we verify it&#39;s done)</li><li>Effort estimate (S = &lt;2h, M = half-day, L = 1–2 days, XL = needs breakdown)</li><li>Risk of the change itself (could it break things?)</li><li>Dependencies on other tasks</li></ul><p>Order tasks into milestones:</p><ul><li><strong>Milestone 0</strong> — Safety net: anything needed before refactoring safely (tests around critical paths, CI gates, backups).</li><li><strong>Milestone 1</strong> — Critical fixes: security and correctness issues.</li><li><strong>Milestone 2</strong> — High-leverage improvements: changes that make all future work easier.</li><li><strong>Milestone 3</strong> — Quality &amp; polish: remaining medium/low items worth doing.</li></ul><p>Flag quick wins (high impact, S effort) separately so they can be done immediately.</p><p>For the top 3 tasks, include a brief implementation sketch (approach, key steps, gotchas).</p><h4 id="final-deliverable-format" tabindex="-1">Final Deliverable Format <a class="header-anchor" href="#final-deliverable-format" aria-label="Permalink to &quot;Final Deliverable Format&quot;">​</a></h4><ul><li>Executive Summary (≤10 sentences: overall health grade A–F with justification, top 3 risks, top 3 opportunities)</li><li>Repo Map</li><li>Audit Report</li><li>Improvement Strategy</li><li>Task Plan (milestones + task table + quick wins)</li><li>Open Questions: anything you need from a human to decide (product intent, deprecation candidates, performance targets)</li></ul><h4 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h4><ul><li>Do NOT modify any code during this audit. Analysis only.</li><li>Do not pad the report. If a dimension is healthy, say so in one sentence and move on.</li><li>Calibrate to the project&#39;s maturity. Don&#39;t recommend enterprise-grade infrastructure for a weekend prototype unless the owner&#39;s goals demand it.</li><li>Analyze the project&#39;s needs and provide recommendations in the most effective ways.</li><li>If the repo is large, prioritize depth in the core 20% of code that does 80% of the work, and note which areas received lighter review.</li></ul><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：572K views / 10K bookmarks 的病毒式 repo audit prompt：四階段（Discovery→Audit→Strategy→Task Plan）結構，8 維度審計 + severity 分級 + milestone 排序的完整框架。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Phase 1 Discovery</strong>：先讀後判——map 目錄結構、辨識慣例，讓建議 fit 既有文化而非對抗它</li><li><strong>Phase 2 Audit 八維度</strong>：Architecture / Code Quality / Security / Testing / Performance / Dependencies / DevEx / Documentation——每個 finding 要求 file:line 實證 + severity 分級</li><li><strong>Phase 3 Strategy</strong>：歸納 3-5 主題 + 明確列出「不修什麼」的 trade-off + 可量測的 done 定義</li><li><strong>Phase 4 Task Plan</strong>：Milestone 0（安全網）→ 1（關鍵修復）→ 2（高槓桿）→ 3（品質打磨），含 S/M/L/XL effort 估算</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>10,421 bookmarks（1.8% bookmark rate——極高實用性信號）</li><li>8 個審計維度 × 4 severity levels</li><li>4 milestone 分級 + quick wins 獨立標記</li><li>「15 high-confidence &gt; 50 speculative」品質原則</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>與 workspace The Loop 高度對應</strong>：Phase 1 = OBSERVE / Phase 2 = IDENTIFY / Phase 3 = PROPOSE / Phase 4 = APPLY 前置 plan——但缺少 TEST 和 RECORD 階段（執行後驗證）</li><li><strong>「facts vs judgments」分離</strong>是優秀設計——對應 core.md 跨切紀律「判斷 vs 決定」，但用在 LLM audit 場景：LLM 容易把 judgment 偽裝成 fact（confident plausibility），需要 grep/test 的機械驗證（unverified_success 閘門）</li><li><strong>缺少迭代閉環</strong>：prompt 產出 report 後結束，沒有 verify-fix-recheck 的 loop——對比 workspace 的 <code>/code-review --fix</code> + PGE healthcheck，這是一次性 audit 而非 loop-driven improvement</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>可直接作為 <code>/code-review</code> 或 <code>/review</code> 的參考框架；milestone 分級可強化現有 SKILL</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>結構嚴謹但本質是 well-known audit checklist 的 prompt 化；「facts vs judgments」分離有價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>10K bookmarks 是強實用性信號；但 prompt 本身無實測效果展示</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>八維度覆蓋全面，severity + effort + risk 三軸評估是工程化設計</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>語言/框架無關，適用任何 repo</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.20/10</strong></td><td>7×0.3+5×0.2+5×0.2+6×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：四階段框架 + 八維度 + milestone 分級可強化 /code-review 和 /review SKILL 的結構化輸出；facts vs judgments 分離值得納入 review-hub</p>',50)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
